/* @lc app=leetcode id=4001 lang=kotlin */ class Solution { fun aggregateTimeSeries(series1: Array<IntArray>, series2: Array<IntArray>): List<List<Int>> = java.util.TreeMap(series1.associate { it[0] to it[1] }).let { ta -> java.util.TreeMap(series2.associate { it[0] to it[1] }).let { tb -> (ta.keys + tb.keys).toSortedSet().map { t -> listOf(t, (ta.ceilingEntry(t)?.value ?: 0) + (tb.ceilingEntry(t)?.value ?: 0)) } } } }